    }

    const messageInputer = new CreateUserMessageInputer();

    // 2. 核心渲染与图像链接生成逻辑
    const VeraRenderer = {
      validForms: ['银月', '红月', '黄月'],
      validMoods: Object.keys(MoodColors),

      // 图像链接生成器
      getAvatarUrl(form, mood) {
        let finalForm = this.validForms.includes(form) ? form : '银月';
        let finalMood = this.validMoods.includes(mood) ? mood : '微笑';
        console.log("最终形态", finalForm, finalMood);
        if(!IS_LOCAL) return picUrlConfig[finalForm][finalMood];
