        // 目前配置为本地前缀，后续可以平滑更改为网络 URL
        const basePath = "asset/image/avatar";
        console.log("路径", `${prefix}/${basePath}/${finalForm}-${finalMood}.png`);
        return `${prefix}/${basePath}/${finalForm}-${finalMood}.png`;
      },

      // 获取最终应该显示的形态文字
      getDisplayForm(form) {
        if (VeraConfigStore.state.isLocked) return VeraConfigStore.state.currentForm;
        return this.validForms.includes(form) ? form : '银月';
      },

      // 初始化所有对话框
      initAll() {

        VeraConfigStore.load();
        document.querySelectorAll('.vera-dialogue-wrapper').forEach(wrapper => {
          const rawForm = wrapper.getAttribute('data-form');
          const rawMood = wrapper.getAttribute('data-mood');

          const finalForm = this.validForms.includes(rawForm) ? rawForm : '银月';
