          const targetColor = MoodColors[finalMood] || MoodColors['默认'];
          wrapper.style.setProperty('--mood-color', targetColor);

          // 初始化面板事件
          this.bindPanelEvents(wrapper);
        });

        // 初始化面板数值
        this.syncPanels();
      },

