          e.stopPropagation();
          document.querySelectorAll('.vera-config-panel.active').forEach(p => {
            if(p !== panel) p.classList.remove('active');
          });
          panel.classList.toggle('active');
        });

        // 监听修改并保存到全局 Store
        lockCheckbox.addEventListener('change', (e) => {
          VeraConfigStore.state.isLocked = e.target.checked;
          VeraConfigStore.save();
        });

        formSelect.addEventListener('change', (e) => {
          VeraConfigStore.state.currentForm = e.target.value;
          // 修改形态时自动勾选锁定
          /*
          if (!VeraConfigStore.state.isLocked) {
             VeraConfigStore.state.isLocked = true;
          }
             */
          VeraConfigStore.save();
        });
      },

      // 仅同步各个对话框中的下拉框和复选框状态，不改变已经渲染的头像
      syncPanels() {
        document.querySelectorAll('.vera-dialogue-wrapper').forEach(wrapper => {
          const lockCheckbox = wrapper.querySelector('.vera-lock-checkbox');
          const formSelect = wrapper.querySelector('.vera-form-select');
          if(lockCheckbox) lockCheckbox.checked = VeraConfigStore.state.isLocked;
          if(formSelect) formSelect.value = VeraConfigStore.state.currentForm;
        });
      }
    };

    // 全局点击关闭面板
    document.addEventListener('click', (e) => {
      if (!e.target.closest('.vera-config-panel') && !e.target.closest('.vera-star-btn')) {
        document.querySelectorAll('.vera-config-panel.active').forEach(p => {
          p.classList.remove('active');
        });
      }
    });

    // 页面加载完成后执行首次渲染
    window.addEventListener('DOMContentLoaded', () => {
      VeraRenderer.initAll();
    });
