                actions_taken: ensureArray(data["关键行动"]),
                butterfly_effects: ensureArray(data["蝴蝶效应"])
            };

            // 修改点：检查当前天数是否已存在记录
            const existingRecordIndex = currentNode.narrative_log.findIndex(log => log.day === currentDay);

            if (existingRecordIndex !== -1) {
                if (!confirm(`[TimeGate] 警告：第 ${currentDay} 天的记录已存在，是否覆盖/追加它？`)) {
                    console.log(`[TimeGate] 操作中止：用户取消了对第 ${currentDay} 天记录的覆盖。`);
                    throw new Error("USER_CANCELLED");
                }
                if(confirm("选择覆盖/追加，是：覆盖，否：追加")){
                    currentNode.narrative_log[existingRecordIndex] = dailyRecord;
                } else{
                    currentNode.narrative_log[existingRecordIndex].actions_taken.push(...dailyRecord.actions_taken);
                    currentNode.narrative_log[existingRecordIndex].butterfly_effects.push(...dailyRecord.butterfly_effects);
                }
                // 确认覆盖

            } else {
                // 不存在，正常推入
                currentNode.narrative_log.push(dailyRecord);
            }

            // 只有在保存成功后才更新总天数，避免取消操作污染数据
            currentNode.exploration_state.days_elapsed = Math.max(currentNode.exploration_state.days_elapsed, currentDay);

            TimeGateDataManager.save();
            console.log(`[TimeGate] 第 ${currentDay} 天记录已更新:`, dailyRecord);
        }

        /**
