        function handleFinish(data) {
            TimeGateDataManager.fetchData();
            const Vera = TimeGateDataManager.veraData;
            const currentNode = Vera.时间之门.当前节点;
            if (!currentNode) {
                throw new Error("没有检测到进行中的时间之门节点，无法进行结算。");
            }

            const nodeId = currentNode.id;

            // 修改点：检查历史节点中是否已存在相同的 ID
            if (Vera.时间之门.历史节点 && Vera.时间之门.历史节点[nodeId]) {
                if (!confirm(`[TimeGate] 警告：已存在 ID 为 ${nodeId} 的结算记录，是否覆盖？`)) {
                    console.log(`[TimeGate] 操作中止：用户取消了节点结算覆盖。`);
                    throw new Error("USER_CANCELLED");
                }
            } else if (Vera.时间之门.历史节点 && Object.values(Vera.时间之门.历史节点).some(
                (v) => {
                    return (v.timeline_info.target_historical_time === currentNode.timeline_info.target_historical_time) 
                        && (v.timeline_info.real_world_entry_time === currentNode.timeline_info.real_world_entry_time)
                }
            )) {
                if (!confirm(`[TimeGate] 警告：疑似存在一致的历史记录，是否继续写入？`)) {
                    console.log(`[TimeGate] 操作中止：用户取消了节点结算覆盖。`);
                    throw new Error("USER_CANCELLED");
                }
            }

            // 写入结算数据
            currentNode.settlement.items_retrieved = ensureArray(data["携带物品"]);
            currentNode.settlement.reality_shifts = ensureArray(data["现实变化"]);
            currentNode.status = "finished";
            if(currentNode.narrative_log.length > 1){
                const sorted_logs = currentNode.narrative_log.sort( function(a, b) {
                    return a.day - b.day
                });
                //console.log(sorted_logs);
                currentNode.narrative_log = sorted_logs;
            }

            // 转移到历史记录中 (持久化存储的源头)
            if (!Vera.时间之门.历史节点) Vera.时间之门.历史节点 = {}; // 确保初始化防报错
            Vera.时间之门.历史节点[nodeId] = JSON.parse(JSON.stringify(currentNode)); // 深拷贝切断引用

            // 清理当前节点
            Vera.时间之门.当前节点 = null;
            TimeGateDataManager.save();

            console.log(`[TimeGate] 节点 ${nodeId} 已结算并归档。`, Vera.时间之门.历史节点[nodeId]);
        }


