        /**
         * 轻量级安全 YAML 解析器 (专门应对键值对及数组列表)
         */
        function parseSimpleYAML(text) {
            const lines = text.split('\n');
            const result = {};
            let currentKey = null;

            for (let line of lines) {
                // 去除右侧空格，保留左侧缩进以便后续判断（如果需要）
                line = line.trimEnd();
                const trimmedLine = line.trim();

                if (!trimmedLine) continue; // 跳过空行

                // 判断是否为数组项: 以 "- " 开头
                if (trimmedLine.startsWith('- ')) {
                    if (currentKey) {
                        if (!Array.isArray(result[currentKey])) {
                            // 如果该键还不是数组，但遇到了数组项，则将其转换为数组
                            result[currentKey] = result[currentKey] ? [result[currentKey]] : [];
                        }
                        // 提取 "- " 之后的内容
                        const arrayItem = trimmedLine.replace(/^-\s*/, '').trim();
                        result[currentKey].push(arrayItem);
                    }
                    continue;
                }

                // 判断是否为键值对: "Key: Value" 或 "Key:"
                const match = trimmedLine.match(/^([^:]+):\s*(.*)$/);
                if (match) {
                    const key = match[1].trim();
                    const value = match[2].trim();
                    currentKey = key;

                    if (value) {
                        result[key] = value;
                    } else {
                        result[key] = []; // 遇到空值，预留为数组
                    }
                }
            }
            return result;
        }

        /**
         * 确保返回值为数组，增强健壮性
         */
        function ensureArray(val) {
            if (!val) return [];
            if (Array.isArray(val)) return val;
            return [val]; // 如果 AI 漏写了 "-" 导致解析成单行字符串，强制包装为数组
        }

