        // ==========================================
        // 3. 核心流：解析正则并动态创建 DOM
        // ==========================================
        function parseAndRenderTimeGate() {
            const container = document.getElementById('chat-container');
            const regex = /<TimeGate\s+type\s*=\s*["']?(init|active|finish)["']?>([\s\S]*?)<\/TimeGate>/g;
            let match;

